// Multilingual HOLDOUT set — written before the multilingual engine code existed (2026-10-16) and never used to
// tune rules. 10 cases per locale configuration (16 configs). Atoms follow the grammar in requirement-benchmark.ts.
// Reference criteria (decided up front, applied identically to every language):
//  - lang:X~  request language, only when no output language is stated; English is never inferred (as before).
//  - lang:X   explicitly requested output language (explicit beats inferred; the inferred atom is then absent).
//  - Chinese 字 / Japanese 文字 / Korean 자 count characters → chars:…; 語/단어/word-units → words:….
//  - chars:N = total maximum; chars:N:item = per-item maximum; chars:A-B = range.
//  - Counts come from digits only (incl. native digits); an indefinite "one/a" (一, एक…) is not a count, like "a" in English.
//  - Nouns are normalized to English singular (tip, idea, question, step, paragraph, sentence, country, example, reason).
export type MLCase = { id: string; locale: string; cat: string; text: string; expect: string[] };
const L = (locale: string, rows: [string, string, string[]][]): MLCase[] => rows.map(([cat, text, expect], i) => ({ id: `h-${locale}-${i + 1}`, locale, cat, text, expect }));

